/**
 * Scenes 1 and 2: the same three-connection echo server drawn as lanes and written as an strace-style call log.
 * The calls are generated by this module for the chosen model; nothing here is output from a real process.
 */
import type { GanttBar, GanttLane } from '../../components/GanttLanes';
import type { LogRow } from '../../components/logRows';
import { barsAt } from '../../core/gantt';
import type { Tone } from '../../core/tone';
import type { Model } from './serve';

export const TRACE_CONNECTIONS = 3;
/** Which connections have a request in each of three rounds: 6 events in all (scripted, so the log reads the same each time). */
export const TRACE_ROUNDS: number[][] = [[0, 2], [1], [0, 1, 2]];
export const ROUND_TICKS = 70;
/** Ticks of work per request in the strace scene. */
export const TRACE_WORK = 4;
/** The strace scene opens on epoll. */
export const DEFAULT_TRACE_MODEL: Model = 'epoll';
const FIRST_ARRIVAL = 2;
/** The listening socket is fd 3 (and the epoll fd), the connections are fds 4 to 6. */
const FIRST_FD = 4;
const FIRST_PID = 101;
const PAYLOAD = '"ping"';

export interface Call {
  id: number;
  t: number;
  lane: string;
  name: string;
  text: string;
  tone: Tone;
}

export interface Echo {
  calls: Call[];
  bars: GanttBar[];
  lanes: GanttLane[];
  end: number;
}

/** The lanes are crowded, so a read, write or EAGAIN diamond carries one letter; the log spells the call out. */
const INSTANT_LABEL: Record<string, string> = { read: 'r', write: 'w', EAGAIN: 'x' };
/** The key to those letters, for the legend. */
export const INSTANT_KEY = 'r = read, w = write, x = EAGAIN';

type RawCall =Omit<Call, 'id'>;

const fdOf = (conn: number) => FIRST_FD + conn;
const roundStart = (r: number) => r * ROUND_TICKS + FIRST_ARRIVAL;
const list = (conns: readonly number[]) => conns.map(fdOf);

export function echoTrace(model: Model, work: number): Echo {
  const end = TRACE_ROUNDS.length * ROUND_TICKS;
  const calls: RawCall[] = [];
  const bars: GanttBar[] = [];
  let barId = 0;
  const bar = (b: Omit<GanttBar, 'id'>) => bars.push({ ...b, id: `b${barId++}` });
  const call = (c: RawCall) => calls.push(c);

  if (model === 'blocking') {
    const lanes: GanttLane[] = Array.from({ length: TRACE_CONNECTIONS }, (_, i) => ({ id: `t${i}`, label: `thread ${i + 1}` }));
    lanes.forEach((lane, conn) => {
      let cursor = 0;
      TRACE_ROUNDS.forEach((ready, r) => {
        if (!ready.includes(conn)) return;
        const t = roundStart(r);
        const pid = `[pid ${FIRST_PID + conn}]`;
        bar({ lane: lane.id, start: cursor, end: t, tone: 'dim', kind: 'blocked', label: 'blocked in read' });
        call({ t, lane: lane.id, name: 'read', text: `${pid} read(${fdOf(conn)}, ${PAYLOAD}, 4096) = 4`, tone: 'ok' });
        bar({ lane: lane.id, start: t, end: t + work, tone: 'hi', label: 'work' });
        call({ t: t + work, lane: lane.id, name: 'write', text: `${pid} write(${fdOf(conn)}, ${PAYLOAD}, 4) = 4`, tone: 'ok' });
        cursor = t + work;
      });
      bar({ lane: lane.id, start: cursor, end, tone: 'dim', kind: 'blocked', label: 'blocked in read' });
    });
    return finish(calls, bars, lanes, end);
  }

  const lanes: GanttLane[] = [{ id: 'loop', label: 'loop thread' }];
  let cursor = 0;
  TRACE_ROUNDS.forEach((ready, r) => {
    const arrive = roundStart(r);
    if (model === 'busy') {
      let t = arrive;
      for (let conn = 0; conn < TRACE_CONNECTIONS; conn++) {
        if (ready.includes(conn)) {
          call({ t, lane: 'loop', name: 'read', text: `read(${fdOf(conn)}, ${PAYLOAD}, 4096) = 4`, tone: 'ok' });
          bar({ lane: 'loop', start: t, end: t + work, tone: 'hi', label: 'work' });
          call({ t: t + work, lane: 'loop', name: 'write', text: `write(${fdOf(conn)}, ${PAYLOAD}, 4) = 4`, tone: 'ok' });
          t += work + 1;
        } else {
          call({ t, lane: 'loop', name: 'EAGAIN', text: `read(${fdOf(conn)}, 0x7f3a2c001000, 4096) = -1 EAGAIN (Resource temporarily unavailable)`, tone: 'orange' });
          t += 1;
        }
      }
      return;
    }
    bar({ lane: 'loop', start: cursor, end: arrive, tone: 'dim', kind: 'wait' });
    const waitText = model === 'select'
      ? `select(7, [4 5 6], NULL, NULL, NULL) = ${ready.length} (in [${list(ready).join(' ')}])`
      : model === 'epoll'
        ? `epoll_wait(3, [${list(ready).map((fd) => `{EPOLLIN, {u32=${fd}}}`).join(', ')}], 64, -1) = ${ready.length}`
        : `io_uring_enter(3, ${ready.length}, 1, IORING_ENTER_GETEVENTS, NULL, 0) = ${ready.length}`;
    call({ t: arrive, lane: 'loop', name: model === 'select' ? 'select' : model === 'epoll' ? 'epoll_wait' : 'io_uring_enter', text: waitText, tone: 'info' });
    let t = arrive + 1;
    for (const conn of ready) {
      if (model === 'uring') {
        bar({ lane: 'loop', start: t, end: t + work, tone: 'hi', label: 'work' });
      } else {
        call({ t, lane: 'loop', name: 'read', text: `read(${fdOf(conn)}, ${PAYLOAD}, 4096) = 4`, tone: 'ok' });
        bar({ lane: 'loop', start: t, end: t + work, tone: 'hi', label: 'work' });
        call({ t: t + work, lane: 'loop', name: 'write', text: `write(${fdOf(conn)}, ${PAYLOAD}, 4) = 4`, tone: 'ok' });
      }
      t += work + 1;
    }
    cursor = t;
  });
  if (model !== 'busy') bar({ lane: 'loop', start: cursor, end, tone: 'dim', kind: 'wait' });
  return finish(calls, bars, lanes, end);
}

/** Numbers the calls in time order (stable within a tick), and adds each call as an instant on its lane. */
function finish(raw: RawCall[], bars: GanttBar[], lanes: GanttLane[], end: number): Echo {
  const laneIndex = (id: string) => lanes.findIndex((l) => l.id === id);
  const ordered = raw.map((c, i) => ({ c, i })).sort((a, b) => a.c.t - b.c.t || laneIndex(a.c.lane) - laneIndex(b.c.lane) || a.i - b.i).map((x) => x.c);
  const calls: Call[] = ordered.map((c, id) => ({ ...c, id }));
  const instants: GanttBar[] = calls.map((c) => ({ id: `call-${c.id}`, lane: c.lane, start: c.t, end: c.t, tone: c.tone, label: INSTANT_LABEL[c.name] ?? c.name }));
  return { calls, bars: [...bars, ...instants], lanes, end };
}

/**
 * The lanes as they stand once call number `step` (0-based) has been made: bars clipped to that call's tick
 * (`barsAt`), and only the call instants up to it (two calls can share a tick, so instants are cut by number, not time).
 */
export function revealed(echo: Echo, step: number): { bars: GanttBar[]; now: number } {
  const now = echo.calls[step]?.t ?? 0;
  const isCall = (b: GanttBar) => b.id.startsWith('call-');
  const shown = barsAt(echo.bars.filter((b) => !isCall(b)), now);
  const instants = echo.bars.filter((b) => isCall(b) && Number(b.id.slice('call-'.length)) <= step);
  return { bars: [...shown, ...instants], now };
}

export const callRows =(echo: Echo): LogRow[] => echo.calls.map((c) => ({ id: c.id, at: `t${c.t}`, tone: c.tone === 'ok' ? undefined : c.tone, text: c.text }));
